import * as dntShim from "../../../_dnt.shims.js";
import { withProjectSourceContext } from "../../shared/project-source-context.js";
import { discoverSchedules } from "../../../src/schedule/index.js";
import { outputTriggerList } from "../trigger-utils.js";
function formatSchedule(schedule) {
    return `${schedule.id} -> ${schedule.target.kind}:${schedule.target.id} (${schedule.schedule})`;
}
export async function handleSchedulesCommand(_args) {
    const projectDir = dntShim.Deno.cwd();
    await withProjectSourceContext(projectDir, async ({ adapter, config }) => {
        const result = await discoverSchedules({
            projectDir,
            adapter,
            config,
            allowHostProjectCodeExecution: true,
        });
        await outputTriggerList({
            command: "schedules",
            items: result.items,
            errors: result.errors,
            formatItem: formatSchedule,
        });
    });
}
